"""Release checks for the separate inverse muscle analysis and video revision."""
from pathlib import Path
import json,hashlib,sys
import numpy as np,imageio_ffmpeg
from PIL import Image
from jump_monitor_data import ROOT,read,atomic
from build_motion_study_reel import BG
from compose_jump_rl_draft_v3 import Draft
OUT=ROOT/'deliverables/jump_rl_study_draft_v3'

def main():
    m=read(OUT/'source_manifest.json');a=read(OUT/'muscle_analysis.json');compat=read(OUT/'training_compatibility.json');assert compat['passed']and compat['qpos_max_error']<1e-10;catalog=read(OUT/'parameter_catalogue.json');assert len(catalog['parameters'])==58 and sum(x['kind']=='posture_timing'for x in catalog['parameters'])==43
    cases={c['key']:c for c in m['cases']};checks=[]
    for key in m['final_four_keys']:
        c=cases[key];f=Path(c['multiview_folder']);z=np.load(f/'muscles.npz');source=np.load(Path(c['folder'])/'motion.npz');assert np.array_equal(source['qpos'],np.load(f/'motion.npz')['qpos']);row=a['cases'][key];error=float(abs(np.einsum('tqn,tn->tq',z['R'],z['force_N'])-z['target']).max());assert error<.01 and np.max(z['passive_force_N']-z['force_N'])<1e-5;assert row['position_error_m']<1e-9 and row['finite_difference_moment_arm_error_m']<1e-4 and row['root_virtual_work_error_m']<1e-7
        mapping=read(f/'conditional_contour_mapping.json');assert {r['group']for r in mapping['mapped']}==set(m['display_muscle_keys']);assert mapping['forces_clipped']is False;expected=round(c['duration_s']*c['multiview_fps']);files=list((f/c['multiview_dir']).glob('frame_*.png'));assert len(files)==expected+1;assert (f/'rear_posters'/f'frame_{c["rear_poster_frame"]:04d}.png').is_file()
        for name in ['study_render_setup.json','rear_posters_setup.json']:
            setup=read(f/name);assert setup['com_marker_visible']is False;setup['display']='Conditional selected leg-group tension / initial successful push-off peak';atomic(f/name,setup)
        checks.append(dict(key=key,moment_balance_max_error_Nm=error,position_error_m=row['position_error_m'],moment_arm_FD_error_m=row['finite_difference_moment_arm_error_m'],muscle_paths=len(row['names']),frames=len(files),relative_push_peaks={g:row['primary_peaks_N'][g]/m['relative_muscle_reference_N'][g]for g in m['display_muscle_keys']}))
    draft=Draft();ghost=[]
    for key,c in cases.items():
        if c['role']!='montage':continue
        impact=draft.data[key]['r']['first_body_floor_contact_s'];n=round(c['duration_s']*c['render_fps'])
        for t in draft.pre_fall_times(key):
            fi=round(t/c['duration_s']*n);actual=fi/n*c['duration_s'];assert actual<impact-.03;ghost.append(dict(key=key,frame=fi,time_s=actual,impact_s=impact))
    source_check=dict(passed=True,cases=checks,pre_fall_memories=ghost,default_training_physics_unchanged=compat,parameter_outputs=58,internal_torque_channels=11,muscle_force_selection_is_conditional=True);atomic(OUT/'source_check.json',source_check)
    if '--sources-only'in sys.argv:print('V3_SOURCE_CHECK_PASS',flush=True);return
    d=read(OUT/'draft_delivery.json');stream=imageio_ffmpeg.read_frames(d['video'],pix_fmt='rgb24');meta=next(stream);assert tuple(meta['size'])==(1080,1920)and meta['fps']==30;count=0;error=0;bg=np.array(BG);targets={round(t*30):name for t,name in[(5.,'controls'),(7.1,'air_controls'),(12.,'learning'),(draft.duration-1.,'summary')]}
    for raw in stream:
        im=np.frombuffer(raw,dtype=np.uint8).reshape(1920,1080,3);error=max(error,int(abs(im[1536:].astype(int)-bg).max()))
        if count in targets:Image.fromarray(im).save(OUT/f'encoded_{targets[count]}.png')
        count+=1
    assert count==d['frames']and error<=4,(count,error);qa=dict(source_check,frames=count,duration_s=count/30,resolution=[1080,1920],footer_blank_px=384,encoded_footer_max_rgb_error=error,video_sha256=hashlib.sha256(Path(d['video']).read_bytes()).hexdigest());atomic(OUT/'delivery_check.json',qa)
    html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jump study · controls and muscles</title><style>body{margin:0;background:#0c1827;color:#e9eff5;font:17px/1.75 system-ui}main{max-width:1100px;margin:auto;padding:24px}h1{font-size:28px}h2{font-size:21px;margin-top:30px}a{color:#77dac7}.grid{display:grid;grid-template-columns:440px 1fr;gap:28px}video{width:100%;max-height:85vh;border-radius:14px}.card{background:#142438;padding:18px;border-radius:12px}small{color:#a8bdce}@media(max-width:780px){.grid{display:block}}</style><main><h1>What can AI change?</h1><p>V3 · DURATION초 · 팔·타이밍·공중 자세 · 누적 실패 잔상 · 다각도 근육 장력</p><div class="grid"><div><video controls playsinline preload="metadata" poster="/rl_draft_v3/preview_multiview.png" src="/rl_draft_v3.mp4"></video><p><a href="/rl_draft_v3.mp4" download>MP4 다운로드</a> · <a href="/rl_draft_v2.html">이전 수정본</a></p></div><div><div class="card"><b>추가 탐색</b><p id="live">불러오는 중…</p><a href="/landing_live.html">실시간 동작·학습 모니터</a></div><h2>세 관절만 조절하는 모델인가?</h2><p>아닙니다. 앞 영상의 세 관절은 대표 표시였습니다. 현재는 좌우 어깨·팔꿈치, 좌우 고관절·무릎·발목, 체간의 <b>11개 내부 토크 채널</b>이 있습니다. 정책 출력 58개는 자세·타이밍 43개와 다섯 관절군의 도약 구동 곡선 15개입니다. 좌우 목표 패턴은 공유하며, 관절 회전은 주로 시상면으로 제한합니다.</p><h2>공중에서도 조절하나?</h2><p>공중의 어깨·팔꿈치·체간·고관절·무릎·발목 목표 자세와 전환, 착지 준비를 조절합니다. 외부 접촉이 없는 비행에서는 내부 토크로 무게중심의 포물선 궤적이나 전체 각운동량을 임의로 바꿀 수 없습니다. 대신 몸과 팔다리의 모양·방향·발 도달 위치와 착지 조건은 달라집니다.</p></div></div><h2>무엇이 점프를 결정하는가</h2><p>지면 구간의 웅크림 깊이·몸통 기울기·팔 스윙·팔 지연·신전 순서·발목 지연·힘 발휘 곡선이 이륙 상태를 만듭니다. 비행 중에는 접기·뻗기와 착지 준비, 접촉 후에는 흡수와 균형 회복을 수행합니다. 영상의 카드는 실제 후보의 파라미터를 사용합니다.</p><p>정책은 한 점프의 파라미터를 한 번에 선택하고 고정된 PD·착지 상태 제어기가 이를 실행합니다. 매 프레임 신경망이 새로운 근육 발화를 고르는 모델은 아닙니다. 브레인·펄스·연결선은 이 계산 흐름의 개념 그림입니다.</p><h2>새로 추가한 근육 장력</h2><p><b>학습과 별도의 역학 후처리</b>입니다. 같은 강체·관절 동작에 표준 근육 경로 416개를 복원하고, 11개 순 관절 토크를 만족하는 비음수 장력 분배를 계산했습니다. 뼈 위치 일치, 길이 미분과 모멘트암 일치, 전체 내부 가상 일, 모멘트 평형을 확인했습니다. 이 해석 모델은 학습 중 힘을 되먹이지 않으며, 기본 학습 동작을 재실행했을 때 원본 관절 궤적과의 차이는 0입니다.</p><p>정규화된 힘 크기와 시간 변화에 대한 규칙으로 <b>하나의 조건부 분배</b>를 선택했습니다. 신경계가 실제로 선택한 유일한 장력, EMG, 피로 또는 최소 대사 에너지의 예측은 아닙니다. 근육별 힘 상한은 추가하지 않았습니다. 하지·체간에는 표준 수동 장력 바닥값을 사용했고, 확인되지 않은 팔·손 수동 장력 바닥값은 생략했습니다. 고정된 보조 좌표와 견갑대·발의 지지 반력은 모두 식별된 상태가 아닙니다.</p><h2>색과 그래프의 의미</h2><p>둔근은 대둔근군, 사두는 광근·대퇴직근, 햄스트링은 네 경로군, 종아리는 비복근·가자미근을 묶었습니다. 그래프는 오른쪽 근육군의 장력 합을 초기 성공안의 같은 근육군 도약 피크로 나눈 값입니다. <b>1.0×는 초기 기준 장력이며 근력 사용률 100%라는 뜻이 아닙니다.</b> 색은 좌우 각각의 같은 기준을 사용하고 다른 부위는 회색으로 남겼습니다. 네 후보 사이에 색·수치 기준을 바꾸지 않았습니다.</p><p>마지막의 전면 사선·측면 동작은 동기화했고, 최종 표에는 같은 단계의 후면 자세를 넣었습니다. 표의 값은 각 근육군의 도약 구간 피크로 발생 시점이 서로 다를 수 있습니다. 작은 글씨·네 겹 토크 그래프를 덜고, 큰 상대 장력 값과 두꺼운 곡선으로 바꿨습니다.</p><h2>실패 장면과 네 단계</h2><p>실제 서로 다른 실패 12건을 사용했습니다. 실제 몸통 접촉 전의 머리가 지면에서 떨어진 자세를 골라 최대 네 개 잔상을 다음 시행에도 유지했습니다. 마지막은 초기 성공 → 중간 개선 두 개 → 확인된 최장 안정 착지의 네 개이며, 2.19 → 2.46 → 2.60 → 2.74m는 이번 편집용 고정 기록입니다. 추가 탐색과 마지막 후보 교체는 별도로 이어집니다.</p><h2>자료</h2><p><a href="/rl_draft_v3/parameter_catalogue.json">실제 58개 파라미터</a> · <a href="/rl_draft_v3/muscle_analysis.json">근육 경로·장력 해석과 N 단위 피크</a> · <a href="/rl_draft_v3/metrics.json">기존 GRF·토크</a> · <a href="/rl_draft_v3/delivery_check.json">영상·계산 검수</a> · <a href="/rl_draft_v3/ANATOMY_CREDITS.md">모델 크레딧</a></p><small>MuJoCo · PPO · MyoSuite/MyoHub · BodyParts3D © DBCLS · Z-Anatomy/BodyExplorer. 장력 경로의 하지 일부는 로컬 Catelli 모델 경로를 보존적인 MuJoCo 경로로 옮긴 기존 프로필을 사용했습니다. 원본·해시·변경 목록은 근육 해석 자료에 포함됩니다.</small></main><script>async function live(){try{let s=await(await fetch('/landing_live/status.json',{cache:'no-store'})).json();document.getElementById('live').textContent=`${s.status} · ${s.training_episodes} trials · ${s.policy_updates} updates · checked ${s.verified?.min_fine_retained_m?.toFixed(2)??'—'} m`;}catch(e){}}live();setInterval(live,5000);</script></html>'''
    (OUT/'index.html').write_text(html.replace('DURATION',f'{count/30:.1f}'),encoding='utf-8');sfile=ROOT/'docs/standing_long_jump_working_state.json';s=read(sfile);s['latest_video_draft']=dict(version=3,folder=str(OUT),video=d['video'],duration_s=count/30,visible_parameter_outputs=58,torque_channels=11,airborne_control='Posture only; contact-free COM ballistic',persistent_pre_fall_ghosts=4,final_views=m['final_views'],conditional_muscle_tension=True,forward_training_still_torque_driven=True,normalization='Initial right-side group push-off peak',last_candidate_replaceable=True);atomic(sfile,s);print('V3_PACKAGE_PASSED',count,error,flush=True)

if __name__=='__main__':main()

